import { distributionInfo } from '@/api/supplier';
import { distributionOrder } from '@/api/order';
import QRCode from 'qrcodejs2';
import Setting from '@/setting';
export default {
  data: function data() {
    return {
      columns: [{
        title: '商品编号',
        key: 'index',
        align: 'center',
        width: 60
      }, {
        title: '商品名称',
        slot: 'store_name',
        align: 'center',
        minWidth: 253
      }, {
        title: '商品规格',
        slot: 'suk',
        align: 'center',
        width: 219
      },
      // {
      //     title: '商品条码',
      //     key: 'bar_code',
      //     align: 'center',
      //     width: 109
      // },
      // {
      //     title: '商品编码',
      //     key: 'code',
      //     align: 'center',
      //     width: 109
      // },
      {
        title: '单价',
        key: 'truePrice',
        align: 'center',
        width: 100
      }, {
        title: '数量',
        key: 'cart_num',
        align: 'center',
        width: 60
      }, {
        title: '金额',
        key: 'subtotal',
        align: 'center',
        width: 100
      }],
      data: {},
      goods: [],
      BaseURL: Setting.apiBaseURL.replace(/adminapi/, ""),
      newArrayData: [],
      site_name: '',
      refund_phone: '',
      refund_address: ''
    };
  },
  created: function created() {
    this.getDistribution();
  },
  mounted: function mounted() {
    this.$nextTick(function () {
      var that = this;
      setTimeout(function () {
        that.creatQrCode();
      }, 200);
    });
  },
  methods: {
    // 生成二维码
    creatQrCode: function creatQrCode() {
      var url = this.BaseURL;
      var qrcode = '';
      this.newArrayData.forEach(function (item, index) {
        var obj = document.getElementById('qrCodeUrl' + index);
        qrcode = new QRCode(obj, {
          text: url,
          // 需要转换为二维码的内容
          width: 90,
          height: 90,
          colorDark: '#000000',
          colorLight: '#ffffff',
          correctLevel: QRCode.CorrectLevel.H
        });
      });
    },
    getDistribution: function getDistribution() {
      var _this = this;
      var header = this.$route.query.status == 1 ? distributionInfo : distributionOrder;
      header(this.$route.query.id).then(function (res) {
        _this.data = res.data;
        _this.goods = res.data.list;
        var data = res.data;
        var newArray = [];
        _this.site_name = data.site_name;
        _this.refund_phone = data.refund_phone;
        _this.refund_address = data.refund_address;
        data.list.forEach(function (i, indexi) {
          var listArray = [];
          var goods = i.list;
          var count = Math.ceil(goods.length / 6);
          for (var j = 0; j < count; j++) {
            var list = goods.slice(j * 6, j * 6 + 6);
            if (list.length) {
              listArray.push(list);
            }
          }
          var num = 6 - listArray[listArray.length - 1].length;
          if (num) {
            for (var z = 0; z < num; z++) {
              listArray[listArray.length - 1].push({
                cart_num: '',
                index: '',
                store_name: '',
                subtotal: '',
                suk: '',
                truePrice: ''
              });
            }
          }
          listArray.forEach(function (x) {
            newArray.push({
              real_name: i.real_name,
              user_address: i.user_address,
              user_phone: i.user_phone,
              freight_price: i.freight_price,
              coupon_price: i.coupon_price,
              vip_true_price: i.vip_true_price,
              use_integral: i.use_integral,
              deduction_price: i.deduction_price,
              pay_price: i.pay_price,
              mark: i.mark,
              order_id: i.order_id,
              pay_time: i.pay_time,
              pay_type_name: i.pay_type_name,
              goodsList: x
            });
          });
        });
        _this.newArrayData = newArray;
      })["catch"](function (err) {
        _this.$Message.error(err.msg);
      });
    }
  }
};
